// The range — product discovery and comparison across the five portfolios.
//
// This page answers "what are the five, and which one?". Everything about a SINGLE portfolio lives
// on that portfolio's own pages (index.html?p=<key> and the seven analysis pages), which a product
// card links into. See docs/architecture/Five_Product_IA.md.
//
// Data: data/portfolios.js (the five books on a common window, generated by
// Src/build_portfolios_dashboard_data.py), data/live_nav.js (the priced NAV since 15 Jul 2026) and
// data/portfolio_books.js (per-portfolio payloads — used here only for the solved risk constraints
// and the series provenance). Nothing on this page is hand-typed data.

/* global Plotly */
(function () {
  const D = window.PORTFOLIOS;
  const el = (id) => document.getElementById(id);
  if (!D) { const s = el("appbar-status"); if (s) s.textContent = "portfolios.js data missing"; return; }
  const LIVE = window.LIVE_NAV || null;
  const BOOKS = window.PORTFOLIO_BOOKS || null;

  const FONT = { family: "-apple-system, Segoe UI, Roboto, sans-serif", size: 11, color: "#46535f" };
  const BASE = { font: FONT, margin: { l: 46, r: 14, t: 10, b: 32 }, paper_bgcolor: "transparent",
    plot_bgcolor: "transparent", separators: ".,",
    hoverlabel: { bgcolor: "#fff", bordercolor: "#dbe2ea", font: { size: 11, color: "#1b2733" }, align: "left" },
    xaxis: { gridcolor: "#eff2f6", zeroline: false, linecolor: "#e3e8ee", ticks: "", tickfont: { size: 10 } },
    yaxis: { gridcolor: "#eff2f6", zeroline: false, linecolor: "#e3e8ee", ticks: "", tickfont: { size: 10 } } };
  const CFG = { displayModeBar: false, responsive: true };

  // Plotly MUTATES the layout object it is handed — it writes `type`, `range` and `autorange` back
  // onto the axis objects. BASE.xaxis was being shared by reference across every chart on the page,
  // so once the growth chart (date x-axis) had drawn, every later chart inherited type:"date" and its
  // range: the asset-class bars all collapsed onto one date and stacked to 500%. Always hand Plotly a
  // fresh layout with freshly cloned axes.
  const L = (extra) => {
    const e = extra || {};
    return Object.assign({}, BASE, e, {
      xaxis: Object.assign({}, BASE.xaxis, e.xaxis || {}),
      yaxis: Object.assign({}, BASE.yaxis, e.yaxis || {}),
    });
  };

  const P5 = D.order;                              // the five products, in house order
  const BENCH = D.bench_order || [];
  const lab = (k) => (D.books[k] || {}).label || k;
  const col = (k) => (D.books[k] || {}).color || "#8b97a3";
  const V = (k) => D.versions[k];
  const M = (k) => D.metrics[k];

  const p1 = (x, d = 1) => (100 * x).toFixed(d) + "%";
  const sgn = (x, suf, d = 1) => (x >= 0 ? "+" : "−") + Math.abs(x).toFixed(d) + suf;
  const fmtD = (s) => new Date(s + "T00:00:00").toLocaleDateString("en-GB",
    { day: "numeric", month: "short", year: "numeric" });

  // ---------------------------------------------------------------- ribbon + framing
  const best = P5.slice().sort((a, b) => M(b).sharpe - M(a).sharpe)[0];
  const deep = P5.slice().sort((a, b) => M(a).mdd - M(b).mdd)[0];
  el("kpi-ribbon").innerHTML = [
    { l: "Products", v: String(P5.length), s: "live since " + fmtD(D.meta.inception) },
    { l: "Common window", v: D.meta.window.start + " – " + D.meta.window.end,
      s: D.meta.window.n + " months, net of cost" },
    { l: "Best risk-adjusted", v: lab(best), s: "Sharpe " + M(best).sharpe.toFixed(2), perf: true },
    { l: "Deepest loss", v: lab(deep), s: p1(M(deep).mdd) + " worst drawdown" },
  ].map((k) => `<div class="kpi${k.perf ? " kpi-perf" : ""}"><div class="kpi-label">${k.l}</div>
      <div class="kpi-value">${k.v}</div><div class="kpi-sub">${k.s}</div></div>`).join("");

  el("range-insight").innerHTML =
    `The five are separated by <strong>job</strong>, not by risk dial. ` +
    P5.map((k) => `<strong>${lab(k)}</strong> ${V(k).role.replace(/ —.*$/, "").toLowerCase()}`).join(" · ") +
    `. Three hold their policy weights by design; <strong>DAA</strong> and <strong>Alpha</strong> act on ` +
    `the macro read. Each card below opens that portfolio's own pages — allocation, holdings, ` +
    `performance, risk, stress and Monte Carlo all follow the product you choose.`;

  el("appbar-status").textContent = `${P5.length} products · as of ${fmtD(D.meta.asof)}`;
  el("status-footer").textContent =
    `Generated by ${D.meta.generator} from ${D.meta.engines.join(", ")} · ` +
    `${D.meta.window.start}–${D.meta.window.end} · ${D.meta.cost_note}`;

  // ---------------------------------------------------------------- 01 product cards
  const liveStat = (k) => {
    if (!LIVE) return null;
    const nm = lab(k), s = LIVE.stats && LIVE.stats[nm];
    return s ? { nav: s.nav, ret: s.ret } : null;
  };
  el("product-cards").innerHTML = P5.map((k) => {
    const v = V(k), m = M(k), ls = liveStat(k);
    const dials = Object.entries(v.dials || {})
      .map(([a, b]) => `<span class="pd-dial">${a} <b>${b}</b></span>`).join("");
    return `<a class="pd-card" href="index.html?p=${k}" style="--pc:${col(k)}">
      <div class="pd-top">
        <div class="pd-name">${v.name}</div>
        <span class="pd-kind ${v.managed === "active" ? "act" : "sta"}">${
          v.managed === "active" ? "actively run" : "policy weights"}</span>
      </div>
      <div class="pd-role">${v.role}</div>
      <p class="pd-thesis">${v.thesis}</p>
      <div class="pd-dials">${dials}<span class="pd-dial">horizon <b>${v.horizon}</b></span></div>
      <div class="pd-stats">
        <div class="pd-stat"><b>${ls ? ls.nav.toFixed(2) : "–"}</b><span>NAV today</span></div>
        <div class="pd-stat"><b class="${ls && ls.ret < 0 ? "neg" : "pos"}">${
          ls ? sgn(100 * ls.ret, "%", 2) : "–"}</b><span>since launch</span></div>
        <div class="pd-stat"><b>${m.cagr ? p1(m.cagr, 1) : "–"}</b><span>backtest CAGR</span></div>
        <div class="pd-stat"><b class="neg">${p1(m.mdd, 1)}</b><span>worst loss</span></div>
      </div>
      <div class="pd-cta">Open ${v.name} <span class="arr">→</span></div>
    </a>`;
  }).join("");

  // ---------------------------------------------------------------- 02 choosing
  el("posn-sub").textContent =
    `${D.meta.window.start}–${D.meta.window.end} backtest · bubble size = worst drawdown · benchmarks in grey`;
  const pts = (keys, kind) => ({
    type: "scatter", mode: "markers+text", name: kind,
    x: keys.map((k) => 100 * M(k).vol), y: keys.map((k) => 100 * M(k).cagr),
    text: keys.map(lab), textposition: "top center",
    textfont: { size: 10, color: kind === "Portfolios" ? "#1b2733" : "#8b97a3" },
    marker: {
      size: keys.map((k) => 12 + Math.abs(100 * M(k).mdd) * 0.55), sizemode: "diameter",
      color: keys.map((k) => (kind === "Portfolios" ? col(k) : "#c9ced6")),
      opacity: kind === "Portfolios" ? 0.85 : 0.5, line: { color: "#fff", width: 1.5 },
    },
    customdata: keys.map((k) => [M(k).sharpe.toFixed(2), (100 * M(k).mdd).toFixed(1)]),
    hovertemplate: "<b>%{text}</b><br>CAGR %{y:.2f}% · vol %{x:.1f}%" +
      "<br>Sharpe %{customdata[0]} · worst loss %{customdata[1]}%<extra></extra>",
  });
  Plotly.newPlot("posn-chart", [pts(BENCH, "Benchmarks"), pts(P5, "Portfolios")],
    L({ showlegend: false, margin: { l: 52, r: 20, t: 14, b: 44 },
      xaxis: Object.assign({}, { ticksuffix: "%", title: { text: "Volatility →", font: { size: 11 } } }),
      yaxis: Object.assign({}, { ticksuffix: "%", title: { text: "CAGR →", font: { size: 11 } } }) }), CFG);
  el("posn-read").innerHTML =
    `The five are spread deliberately along the risk axis — from <strong>${lab(P5[0])}</strong> at ` +
    `${p1(M(P5[0]).vol)} volatility to <strong>${lab(P5[P5.length - 1])}</strong> at ` +
    `${p1(M(P5[P5.length - 1]).vol)} — but they are not the same book at five settings: each holds a ` +
    `different sleeve set, which is what §04 shows. Bubble size is the worst drawdown, so a large ` +
    `bubble high and left is the combination worth having.`;

  el("choose-table").innerHTML = `<table class="dtbl"><thead><tr><th>Portfolio</th><th>Built for</th>
    <th class="num">Horizon</th></tr></thead><tbody>` +
    P5.map((k) => `<tr><td><span class="swatch" style="background:${col(k)}"></span>
      <b>${lab(k)}</b></td><td class="z">${V(k).role}</td>
      <td class="num z">${V(k).horizon}</td></tr>`).join("") +
    `</tbody></table><p class="read" style="margin-top:.5rem">Reference blend per portfolio: ` +
    P5.map((k) => `${lab(k)} → ${V(k).reference}`).join(" · ") + `.</p>`;

  // ---------------------------------------------------------------- 03 side by side
  const dates = D.series.dates;
  // Null-safe: a benchmark that starts later than the common window (MSCI ACWI and its blends begin
  // 2003-02) is null before its first observation and must leave a gap rather than compound a NaN
  // through the whole series. That is exactly how "$NaN" reached this page before.
  const navOf = (k) => {
    let a = null;
    return (D.series.returns[k] || []).map((r) => {
      if (r == null) return a;                 // gap before the series starts, flat if mid-series
      a = (a == null ? 1 : a) * (1 + r);
      return a;
    });
  };
  const NAV = {}; [...P5, ...BENCH].forEach((k) => { NAV[k] = navOf(k); });
  const endv = (k) => { const v = NAV[k]; for (let i = v.length - 1; i >= 0; i--) if (v[i] != null) return v[i]; return NaN; };
  const on = new Set([...P5, "acwi6040"]);
  el("growth-sub").textContent =
    `${D.meta.window.start}–${D.meta.window.end}, rebased to $1 · ${D.meta.cost_note}`;

  function controls() {
    el("growth-controls").innerHTML = [...P5, ...BENCH].map((k) =>
      `<button class="chip${on.has(k) ? " sel" : ""}" data-k="${k}">${lab(k)}</button>`).join("");
    el("growth-controls").querySelectorAll(".chip").forEach((b) => {
      b.onclick = () => { const k = b.dataset.k; on.has(k) ? on.delete(k) : on.add(k); controls(); growth(); };
    });
  }
  function growth() {
    const tr = [...P5, ...BENCH].filter((k) => on.has(k)).map((k) => ({
      x: dates, y: NAV[k], name: lab(k), type: "scatter", mode: "lines",
      line: { color: col(k), width: P5.includes(k) ? 2.1 : 1.3, dash: P5.includes(k) ? "solid" : "dot" },
      hovertemplate: "$%{y:.2f}<extra>" + lab(k) + "</extra>",
    }));
    Plotly.react("growth-chart", tr, L({
      showlegend: false, hovermode: "x unified",
      yaxis: Object.assign({}, { type: "log", tickprefix: "$",
        title: { text: "Growth of $1 (log)", font: { size: 10 } } }),
    }), CFG);
    const led = P5.slice().sort((a, b) => endv(b) - endv(a));
    el("growth-read").innerHTML =
      `Over ${D.meta.window.start}–${D.meta.window.end}: ` +
      led.map((k) => `<strong>${lab(k)}</strong> $${endv(k).toFixed(2)}`).join(" · ") +
      `. A log axis is used because ${p1(M(led[0]).cagr)} and ${p1(M(led[led.length - 1]).cagr)} a year ` +
      `cannot be compared fairly on a linear one. The ranking here is a backtest of today's books — ` +
      `see the provenance note directly below the chart.`;
  }
  controls(); growth();

  // provenance: what this 30-year series actually is. Sourced from the per-portfolio payload.
  (function provenance() {
    const host = el("growth-prov"); if (!host || !BOOKS) return;
    const anyKey = P5.find((k) => BOOKS.books && BOOKS.books[k]);
    const pv = anyKey && BOOKS.books[anyKey].provenance;
    if (!pv) return;
    const backtest = pv.series[Object.keys(pv.series).find((n) => pv.series[n].basis === "backtest")];
    const live = pv.series["Live NAV"];
    host.innerHTML = `<div class="provenance">
      <p class="pv-head">${pv.headline}</p>
      <div class="pv-row"><span class="pv-tag pv-back">backtest</span>
        <span class="pv-name">The series on this chart</span>
        <span class="pv-meta"><b>Window</b> ${backtest.window} · <b>Weights</b> ${backtest.weights}
          · <b>Rebalance</b> ${backtest.rebalance} · <b>Costs</b> ${backtest.costs}</span>
        <span class="pv-note">${backtest.note}</span></div>
      ${live ? `<div class="pv-row"><span class="pv-tag pv-live">live</span>
        <span class="pv-name">Live NAV — on the Live NAV page</span>
        <span class="pv-meta"><b>Window</b> ${live.window} · <b>Weights</b> ${live.weights}
          · <b>Costs</b> ${live.costs}</span>
        <span class="pv-note">${live.note}</span></div>` : ""}
    </div>`;
  })();

  // metric panel
  (function metrics() {
    const rows = [["CAGR", "cagr", "pct", +1], ["Volatility", "vol", "pct", -1],
      ["Sharpe", "sharpe", "num", +1], ["Sortino", "sortino", "num", +1],
      ["Worst loss", "mdd", "pct", +1], ["Calmar", "calmar", "num", +1],
      ["CVaR 5%", "cvar5", "pct", +1], ["Beta to 60/40", "beta_6040", "num", 0]];
    const cols = [...P5, "acwi6040", "spy"];
    let h = `<table class="dtbl"><thead><tr><th>Metric</th>` +
      cols.map((k) => `<th class="num" style="color:${col(k)}">${lab(k)}</th>`).join("") + `</tr></thead><tbody>`;
    rows.forEach(([label, f, kind, dir]) => {
      const vals = P5.map((k) => M(k)[f]);
      const bestv = dir === 0 ? null : (dir > 0 ? Math.max(...vals) : Math.min(...vals));
      h += `<tr><td class="strong">${label}</td>` + cols.map((k) => {
        const v = M(k)[f];
        const isBest = bestv != null && P5.includes(k) && Math.abs(v - bestv) < 1e-9;
        const txt = kind === "pct" ? p1(v, kind === "pct" && f === "cagr" ? 2 : 1) : v.toFixed(2);
        return `<td class="num${isBest ? " strong" : ""}"${isBest ? ' style="background:rgba(47,125,94,.10)"' : ""}>${txt}</td>`;
      }).join("") + `</tr>`;
    });
    el("metric-table").innerHTML = h + `</tbody></table>
      <p class="read" style="margin-top:.5rem">Green marks the best of the five portfolios on that row.
        Benchmarks are shown for context and are not ranked.</p>`;
  })();

  // drawdown
  (function drawdown() {
    const ddOf = (k) => { let pk = -Infinity; return NAV[k].map((v) => {
      if (v == null) return null; pk = Math.max(pk, v); return 100 * (v / pk - 1); }); };
    const tr = [{ x: dates, y: ddOf("acwi6040"), name: lab("acwi6040"), type: "scatter", mode: "lines",
      line: { color: "#c9932b", width: 1.1, dash: "dot" }, fill: "tozeroy", fillcolor: "rgba(201,147,43,0.08)",
      hovertemplate: "%{y:.1f}%<extra>" + lab("acwi6040") + "</extra>" }]
      .concat(P5.map((k) => ({ x: dates, y: ddOf(k), name: lab(k), type: "scatter", mode: "lines",
        line: { color: col(k), width: 1.8 }, hovertemplate: "%{y:.1f}%<extra>" + lab(k) + "</extra>" })));
    Plotly.newPlot("dd-chart", tr, L({ showlegend: false, hovermode: "x unified",
      yaxis: Object.assign({}, { ticksuffix: "%" }) }), CFG);
    const shallow = P5.slice().sort((a, b) => M(b).mdd - M(a).mdd)[0];
    el("dd-read").innerHTML =
      `<strong>${lab(shallow)}</strong> has the shallowest worst loss of the five at ${p1(M(shallow).mdd)}, ` +
      `against ${p1(M("acwi6040").mdd)} for the balanced benchmark. ` +
      `<strong>${lab(deep)}</strong> is the deepest at ${p1(M(deep).mdd)} — which is the mandate ` +
      `working, not failing: it carries equity-level risk on purpose.`;
  })();

  // calendar year
  (function annual() {
    const yrs = {};
    dates.forEach((d, i) => {
      const y = d.slice(0, 4);
      (yrs[y] = yrs[y] || []).push(i);
    });
    const years = Object.keys(yrs).sort();
    const yr = (k) => years.map((y) => {
      const rs = yrs[y].map((i) => D.series.returns[k][i]);
      if (rs.some((r) => r == null)) return null;          // partial year: do not imply a full one
      return 100 * (rs.reduce((a, r) => a * (1 + r), 1) - 1);
    });
    const tr = P5.map((k) => ({ type: "bar", name: lab(k), x: years, y: yr(k), marker: { color: col(k) },
      hovertemplate: "%{y:.1f}%<extra>" + lab(k) + "</extra>" }))
      .concat([{ type: "scatter", mode: "markers", name: lab("acwi6040"), x: years, y: yr("acwi6040"),
        marker: { color: "#c9932b", size: 6, symbol: "diamond" },
        hovertemplate: "%{y:.1f}%<extra>60/40</extra>" }]);
    Plotly.newPlot("annual-chart", tr, L({ barmode: "group", showlegend: false,
      margin: { l: 44, r: 10, t: 10, b: 40 }, yaxis: Object.assign({}, { ticksuffix: "%" }),
      xaxis: Object.assign({}, { tickangle: -45, tickfont: { size: 8 } }) }), CFG);
    const b = yr("acwi6040");
    const wins = P5.map((k) => [k, yr(k).filter((v, i) => v != null && b[i] != null && v > b[i]).length]);
    el("annual-read").innerHTML =
      `Against the balanced benchmark, year by year over the ${
        years.filter((y, i) => yr("acwi6040")[i] != null).length} complete calendar years both cover: ` +
      wins.sort((x, y) => y[1] - x[1]).map(([k, n]) => `<strong>${lab(k)}</strong> ${n}`).join(" · ") +
      `. Diamonds mark the 60/40.`;
  })();

  // ---------------------------------------------------------------- 04 built differently
  (function sleeveMatrix() {
    const all = [];
    P5.forEach((k) => Object.keys(V(k).sleeves).forEach((s) => { if (!all.includes(s)) all.push(s); }));
    const labels = D.sleeve_labels || {};
    const classOf = D.class_of || {};
    // group by platform class so the matrix reads as a book, not an alphabetical list
    const order = [];
    (D.platform_classes || []).forEach((c) => {
      all.filter((s) => classOf[s] === c)
         .sort((a, b) => Math.max(...P5.map((k) => V(k).sleeves[b] || 0))
                       - Math.max(...P5.map((k) => V(k).sleeves[a] || 0)))
         .forEach((s) => order.push([c, s]));
    });
    all.forEach((s) => { if (!order.some((x) => x[1] === s)) order.push([classOf[s] || "Other", s]); });

    const maxw = Math.max(...order.map(([, s]) => Math.max(...P5.map((k) => V(k).sleeves[s] || 0))));
    const shade = (w) => `rgba(48,131,180,${(0.05 + Math.min(w / maxw, 1) * 0.8).toFixed(3)})`;

    let html = `<div class="smx">
      <div class="smx-h smx-lab">Sleeve</div>` +
      P5.map((k) => `<div class="smx-h smx-pf" style="--pc:${col(k)}">${lab(k)}</div>`).join("") +
      `<div class="smx-h smx-cnt">held</div>`;
    let lastClass = null;
    order.forEach(([cls, s]) => {
      if (cls !== lastClass) {
        html += `<div class="smx-group">${cls}</div>`;
        lastClass = cls;
      }
      const held = P5.filter((k) => (V(k).sleeves[s] || 0) > 0.0005).length;
      html += `<div class="smx-lab" title="${labels[s] || s}">${labels[s] || s}</div>` +
        P5.map((k) => {
          const w = V(k).sleeves[s] || 0;
          if (w <= 0.0005) {
            return `<div class="smx-c smx-zero" title="bounded to zero by ${lab(k)}'s mandate">\u2013</div>`;
          }
          const strong = w / maxw > 0.55;
          return `<div class="smx-c" style="background:${shade(w)};color:${strong ? "#fff" : "#1b2733"}"
              title="${lab(k)} · ${labels[s] || s} ${(100 * w).toFixed(1)}%">${(100 * w).toFixed(1)}</div>`;
        }).join("") +
        `<div class="smx-c smx-cnt">${held}<i>/5</i></div>`;
    });
    html += `</div>`;
    el("sleeve-matrix").innerHTML = html;

    const shared = all.filter((s) => P5.every((k) => (V(k).sleeves[s] || 0) > 0.0005));
    const unique = all.filter((s) => P5.filter((k) => (V(k).sleeves[s] || 0) > 0.0005).length === 1);
    el("matrix-read").innerHTML =
      `${all.length} sleeves across the range, grouped by asset class and shaded by weight. ` +
      `<strong>${shared.length}</strong> are held by all five` +
      (shared.length ? ` (${shared.map((s) => labels[s] || s).join(", ")})` : "") +
      `; <strong>${unique.length}</strong> by exactly one` +
      (unique.length ? ` \u2014 ${unique.map((s) => `${labels[s] || s} in ${
        lab(P5.find((k) => (V(k).sleeves[s] || 0) > 0.0005))}`).join(", ")}` : "") +
      `. A dash is not a weight the optimiser happened to set to zero: it is a holding that ` +
      `portfolio's mandate bounds out entirely.`;
  })();

  (function alloc() {
    const cls = D.platform_classes;
    const tr = cls.map((c, i) => ({
      type: "bar", name: c, x: P5.map(lab), y: P5.map((k) => 100 * (V(k).weights[c] || 0)),
      marker: { color: ["#3083b4", "#5b8c9f", "#d68a13", "#2f7d5e", "#c9ced6", "#8a6bb1"][i % 6] },
      hovertemplate: "%{x} · " + c + " %{y:.1f}%<extra></extra>",
    }));
    Plotly.newPlot("alloc-chart", tr, L({ barmode: "stack",
      legend: { orientation: "h", y: -0.18, font: { size: 9 } }, margin: { l: 40, r: 10, t: 8, b: 56 },
      yaxis: Object.assign({}, { ticksuffix: "%" }) }), CFG);
    const eq = P5.map((k) => [k, 100 * (V(k).weights.Equities || 0)]).sort((a, b) => b[1] - a[1]);
    el("alloc-read").innerHTML =
      `Equity weight runs from <strong>${eq[0][1].toFixed(0)}%</strong> in ${lab(eq[0][0])} to ` +
      `<strong>${eq[eq.length - 1][1].toFixed(0)}%</strong> in ${lab(eq[eq.length - 1][0])}. ` +
      `${D.meta.taxonomy_note || ""}`;
  })();

  (function fi() {
    const legs = ["Govt", "IG", "TIPS", "HY"];
    let h = `<table class="dtbl"><thead><tr><th>FI leg (% of book)</th>` +
      P5.map((k) => `<th class="num" style="color:${col(k)}">${lab(k)}</th>`).join("") +
      `</tr></thead><tbody>`;
    legs.forEach((l) => {
      h += `<tr><td class="strong">${l}</td>` + P5.map((k) => {
        const v = 100 * ((V(k).fi_of_book || {})[l] || 0);
        return `<td class="num${v > 0.05 ? "" : " z"}">${v > 0.05 ? v.toFixed(1) + "%" : "–"}</td>`;
      }).join("") + `</tr>`;
    });
    el("fi-table").innerHTML = h + `</tbody></table>`;
    const noIG = P5.filter((k) => 100 * ((V(k).fi_of_book || {}).IG || 0) < 0.05);
    el("fi-read").innerHTML =
      `Fixed income is government-led across the range. ` +
      (noIG.length ? `<strong>${noIG.map(lab).join(", ")}</strong> hold no investment-grade credit at all ` +
        `— the sleeve is bounded to zero by mandate rather than optimised away. ` : "") +
      `No portfolio in the range holds mortgage bonds.`;
  })();

  (function constraints() {
    if (!BOOKS || !BOOKS.books) { el("constraint-table").innerHTML = ""; return; }
    let h = `<table class="dtbl"><thead><tr><th>Constraint</th>` +
      P5.map((k) => `<th class="num" style="color:${col(k)}">${lab(k)}</th>`).join("") +
      `</tr></thead><tbody>`;
    const get = (k) => (BOOKS.books[k] || {}).risk || {};
    const row = (label, f, suf) => {
      h += `<tr><td class="strong">${label}</td>` + P5.map((k) => {
        const v = get(k)[f];
        return `<td class="num${v == null ? " z" : ""}">${v == null ? "–" : v.toFixed(1) + suf}</td>`;
      }).join("") + `</tr>`;
    };
    row("Volatility cap", "vol_budget", "%");
    row("Forecast volatility", "forecast_vol", "%");
    row("Drawdown cap (solved under)", "dd_budget", "%");
    row("Drawdown cap (declared)", "dd_declared", "%");
    row("Owner mandate limit", "dd_limit", "%");
    el("constraint-table").innerHTML = h + `</tbody></table>`;
    const loose = P5.filter((k) => get(k).cap_loosened);
    el("constraint-read").innerHTML =
      `These are the caps the optimiser was actually held to, read from the build record rather than ` +
      `from a declaration. ` +
      (loose.length
        ? `<strong>${loose.map(lab).join(", ")}</strong>: the declared drawdown cap was infeasible on ` +
          `the estimation window and the book was solved under the tightest feasible cap instead — ` +
          `so the declared figure alone would misstate what the book was held to. `
        : "") +
      `A construction cap is not a monitoring limit: it bound the solver once, at build time. ` +
      `Only ${P5.filter((k) => get(k).dd_limit != null).map(lab).join(", ") || "one portfolio"} carries ` +
      `an owner-set loss limit in the record.`;
  })();

  // ---------------------------------------------------------------- 05 crisis
  (function crises() {
    const eps = D.crises;
    const tr = P5.map((k) => ({ type: "bar", name: lab(k), x: eps.map((e) => e.name),
      y: eps.map((e) => 100 * e.returns[k]), marker: { color: col(k) },
      hovertemplate: "%{x} · " + lab(k) + " %{y:.1f}%<extra></extra>" }))
      .concat([{ type: "scatter", mode: "markers", name: "60/40", x: eps.map((e) => e.name),
        y: eps.map((e) => 100 * e.returns.acwi6040), marker: { color: "#c9932b", size: 9, symbol: "diamond" },
        hovertemplate: "%{x} · 60/40 %{y:.1f}%<extra></extra>" }]);
    Plotly.newPlot("crisis-chart", tr, L({ barmode: "group", showlegend: false,
      margin: { l: 44, r: 10, t: 10, b: 62 }, yaxis: Object.assign({}, { ticksuffix: "%" }),
      xaxis: Object.assign({}, { tickangle: -22, tickfont: { size: 9 } }) }), CFG);

    let h = `<table class="dtbl"><thead><tr><th>Episode</th>` +
      P5.map((k) => `<th class="num" style="color:${col(k)}">${lab(k)}</th>`).join("") +
      `<th class="num z">60/40</th></tr></thead><tbody>`;
    eps.forEach((e) => {
      const b = e.returns.acwi6040;
      h += `<tr><td class="strong">${e.name}<span class="z" style="display:block;font-size:.7rem">${e.start} – ${e.end}</span></td>` +
        P5.map((k) => {
          const v = 100 * e.returns[k], beat = e.returns[k] > b;
          return `<td class="num ${v < 0 ? "neg" : "pos"}"${beat ? ' style="font-weight:700"' : ""}>${v.toFixed(1)}%</td>`;
        }).join("") + `<td class="num z">${(100 * b).toFixed(1)}%</td></tr>`;
    });
    el("crisis-table").innerHTML = h + `</tbody></table>`;
    const wins = P5.map((k) => [k, eps.filter((e) => e.returns[k] > e.returns.acwi6040).length]);
    wins.sort((a, b) => b[1] - a[1]);
    el("crisis-read").innerHTML =
      `Bold beats the balanced benchmark in that episode. ` +
      wins.map(([k, n]) => `<strong>${lab(k)}</strong> ${n} of ${eps.length}`).join(" · ") +
      `. The conservative end of the range is doing exactly what it exists for here — the question ` +
      `for the growth end is whether the recovery pays for the hole.`;
  })();

  // ---------------------------------------------------------------- 06 the active layer
  (function active() {
    const act = P5.filter((k) => V(k).managed === "active");
    const sta = P5.filter((k) => V(k).managed !== "active");
    el("active-sub").textContent =
      `${act.map(lab).join(" and ")} act on the confirmed MRS regime · ${sta.map(lab).join(", ")} do not`;
    const cur = D.da.timeline.state[D.da.timeline.state.length - 1];
    el("da-map").innerHTML = D.da.states.map((rg) => {
      const t = D.da.class_tilt[rg] || {};
      const eq = t.Equities || 0;
      const mf = D.da.trend_by_state ? D.da.trend_by_state[rg] : null;
      return `<div class="scn${rg === cur ? " scn-cur" : ""}">
        <div class="scn-name">${rg}${rg === cur ? " · now" : ""}</div>
        <div class="scn-stance">equities ${sgn(eq, "pp")} vs the static base</div>
        <div class="scn-bar"><span style="width:${Math.min(Math.abs(eq) * 6, 100)}%;background:${eq >= 0 ? "#2f7d5e" : "#c0392b"}"></span></div>
        <div class="scn-meta">${D.da.months_in_state[rg]} months in window${
          mf != null ? ` · trend sleeve ${(100 * mf).toFixed(1)}%` : ""}</div>
      </div>`;
    }).join("");
    el("da-map-read").innerHTML =
      `Three of the five hold their policy weights by design — for <strong>${sta.map(lab).join(", ")}</strong> ` +
      `there is no active layer and their attribution is zero by construction, not by underperformance. ` +
      `<strong>${act.map(lab).join(" and ")}</strong> size their sleeves to the confirmed regime on a ` +
      `one-month lag. The map is pre-committed: the regime picks the book, with no discretion at trade ` +
      `time. Over the window it switched <strong>${D.da.switches}</strong> times, one-way turnover ` +
      `${(100 * D.da.turnover_oneway_yr).toFixed(0)}%/yr, cost drag ~${D.da.cost_drag_bp_yr.toFixed(0)}bp/yr ` +
      `(all results net). MRS reads <strong>${cur}</strong> today.`;

    const t = D.da.timeline;
    Plotly.newPlot("regime-chart", [{
      type: "scatter", mode: "lines", name: "MRS composite", x: t.dates, y: t.composite,
      line: { color: "#0e2233", width: 1.8 },
      hovertemplate: "composite %{y:.2f}<extra>%{x}</extra>",
    }], L({ showlegend: false,
      yaxis: Object.assign({}, { title: { text: "MRS composite", font: { size: 10 } },
        zeroline: true, zerolinecolor: "#c5cfd9" }) }), CFG);
    const counts = D.da.states.map((s) => `${s} ${D.da.months_in_state[s]}`).join(" · ");
    el("regime-read").innerHTML =
      `The composite is the macro read the active portfolios size against — it is produced by ` +
      `${D.da.source}, not formed here, so the platform has one regime vocabulary rather than two. ` +
      `Months per state: ${counts}. Below zero is where the defensive books are held.`;

    el("da-caveats").innerHTML = (D.da.caveats || []).map((c) =>
      `<div class="flag"><span class="flag-ic">⚠️</span><span>${c}</span></div>`).join("");
  })();

  // ---------------------------------------------------------------- 07 gates
  (function gates() {
    el("gates-table").innerHTML = `<table class="dtbl"><thead><tr><th>Owner</th><th>Open item</th>
      </tr></thead><tbody>` + D.gates.map((g) =>
      `<tr><td class="strong">${g.owner}</td><td class="z">${g.item}</td></tr>`).join("") +
      `</tbody></table>`;
    el("gates-read").innerHTML =
      `All five have been live since <strong>${fmtD(D.meta.inception)}</strong> with a priced daily NAV. ` +
      `These ${D.gates.length} items are open decisions and checks, not blockers to the funds running — ` +
      `the long series on this page remains a backtest either way, and the real record is on the Live NAV page.`;
  })();
})();
